import re
import sqlite3
import subprocess
from datetime import datetime, timezone
PORTAL_DB_PATH = '/var/data/freight_portal.db'
ALLOWED_ROLES = {'viewer', 'dispatcher', 'admin'}
EMAIL_PATTERN = re.compile('^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$')
PERMISSION_SYNC_SCRIPT = '/opt/freight_portal/bin/sync_permissions.sh'

def grant_carrier_portal_access(user_email: str, carrier_account_id: str, role: str, granted_by: str) -> dict:
    if not user_email or not EMAIL_PATTERN.match(user_email):
        return {'ok': False, 'error': 'invalid email'}
    if role not in ALLOWED_ROLES:
        return {'ok': False, 'error': 'invalid role'}
    if not carrier_account_id.strip():
        return {'ok': False, 'error': 'carrier_account_id required'}
    if not granted_by.strip():
        return {'ok': False, 'error': 'granted_by required'}
    conn = sqlite3.connect(PORTAL_DB_PATH)
    try:
        account = conn.execute('SELECT 1 FROM carrier_accounts WHERE id = ?', (carrier_account_id,)).fetchone()
        if account is None:
            return {'ok': False, 'error': 'carrier account not found'}
        user = conn.execute('SELECT id FROM portal_users WHERE email = ?', (user_email.lower(),)).fetchone()
        if user is None:
            return {'ok': False, 'error': 'user not found'}
        now = datetime.now(timezone.utc).isoformat()
        conn.execute('INSERT INTO carrier_access (user_id, carrier_account_id, role, granted_at) VALUES (?, ?, ?, ?) ON CONFLICT(user_id, carrier_account_id) DO UPDATE SET role = excluded.role, granted_at = excluded.granted_at', (user[0], carrier_account_id, role, now))
        conn.execute('INSERT INTO access_audit_log (user_id, carrier_account_id, role, granted_by, created_at) VALUES (?, ?, ?, ?, ?)', (user[0], carrier_account_id, role, granted_by, now))
        conn.commit()
        # Refresh cached permissions for the carrier account
        sync = subprocess.run([PERMISSION_SYNC_SCRIPT, '--account', carrier_account_id], capture_output=True, text=True, timeout=60)
        return {'ok': True, 'user_id': user[0], 'role': role, 'sync_exit_code': sync.returncode}
    finally:
        conn.close()
